test('isPriority', async (t) => {
  await t.test('accepts known values', () => {
    for (const p of PRIORITIES) assert.equal(isPriority(p), true);
  });

  await t.test('rejects unknown and non-string values', () => {
    for (const value of ['URGENT', '', 'medium', null, undefined, 3, {}]) {
      assert.equal(isPriority(value), false);
    }
  });

  await t.test('is not fooled by inherited properties', () => {
